// ========================================================
// STAGE 4: APPLICATION STUDIO & ANTI-HALLUCINATION GATE
// ========================================================
const prev = $('Filter High Match Score (>= 60)').first().json;
const job = prev.job;
const cand = prev.candidate;
const match = prev.match;

let draftCoverLetter = '';
if ($json && $json.candidates && $json.candidates[0]?.content?.parts?.[0]?.text) {
  draftCoverLetter = $json.candidates[0].content.parts[0].text.trim();
}

if (!draftCoverLetter) {
  const verifiedPoints = cand.resume_facts.slice(0, 2).map(fact => `• ${fact}`).join('\n');
  draftCoverLetter = 
`Yth. Tim Rekrutmen ${job.company},\n\n` +
`Saya menulis untuk menyatakan ketertarikan mendalam pada posisi ${job.title}. ` +
`Dengan spesialisasi dalam arsitektur backend terdistribusi dan integrasi pipeline AI, keahlian terverifikasi saya mencakup: ${match.matched_skills.join(', ')}.\n\n` +
`Rekam jejak terverifikasi saya meliputi:\n` +
`${verifiedPoints}\n\n` +
`Portofolio dan draf ini disiapkan dengan integritas data 100% dari profil kandidat ${cand.full_name}.\n\n` +
`Salam,\n${cand.full_name}`;
}

// Quality Gate: zero tolerance for placeholders or hallucinated claims
const forbidden = ['[company]', '[achievement]', '[name]', 'guaranteed', 'fake'];
const violations = forbidden.filter(word => draftCoverLetter.toLowerCase().includes(word));
if (violations.length > 0) {
  throw new Error(`Quality Gate Violation: Found unverified token (${violations.join(', ')})`);
}

const application = {
  application_id: `app-${Date.now()}-${Math.floor(Math.random()*1000)}`,
  candidate_id: cand.candidate_id,
  job_id: job.external_id,
  cover_letter: draftCoverLetter,
  facts_used: cand.resume_facts,
  status: 'pending_approval',
  created_at: new Date().toISOString()
};

return [{ json: { job, candidate: cand, match, application } }];

// ========================================================
// STAGE 5: HUMAN APPROVAL PACKAGE BUILDER
// ========================================================
const job = $json.job;
const match = $json.match;
const app = $json.application;
const cand = $json.candidate;

const summaryText = 
`*REKOMENDASI LOWONGAN BARU (SCORE: ${match.score}/100)*\n\n` +
`*Posisi:* ${job.title}\n` +
`*Perusahaan:* ${job.company}\n` +
`*Lokasi:* ${job.location}\n` +
`*Kandidat:* ${cand.full_name}\n` +
`*Confidence:* ${match.confidence.toUpperCase()}\n` +
`*Skill Cocok:* ${match.matched_skills.join(', ')}\n` +
`*Kekurangan:* ${match.missing_requirements.slice(0, 3).join(', ') || 'Tidak ada'}\n\n` +
`*Preview Draf Cover Letter:*\n${app.cover_letter.slice(0, 250)}...\n\n` +
`URL: ${job.url}`;

const approvalPackage = {
  application_id: app.application_id,
  text: summaryText,
  inline_keyboard: [
    [
      { text: 'Setujui Lamaran', callback_data: `approve:${app.application_id}` },
      { text: 'Tolak', callback_data: `reject:${app.application_id}` }
    ],
    [
      { text: 'Minta Revisi Draf', callback_data: `edit:${app.application_id}` }
    ]
  ]
};

return [{ json: { ...$json, approvalPackage } }];

// ========================================================
// STAGE 6: TELEGRAM APPROVAL RESPONSE HANDLER
// ========================================================
const item = $json;
let action = 'unknown';
let appId = '';
let reviewer = 'Telegram User';

if (item.callback_query) {
  const data = item.callback_query.data || '';
  const parts = data.split(':');
  action = parts[0] || 'unknown';
  appId = parts[1] || '';
  reviewer = item.callback_query.from.first_name || 'Reviewer';
} else if (item.message && item.message.text) {
  const text = item.message.text;
  if (text.startsWith('/approve_')) {
    action = 'approve';
    appId = text.replace('/approve_', '');
  } else if (text.startsWith('/reject_')) {
    action = 'reject';
    appId = text.replace('/reject_', '');
  }
}

const decisionMap = {
  approve: 'approved',
  reject: 'rejected',
  edit: 'changes_requested'
};

return [{
  json: {
    application_id: appId,
    decision: decisionMap[action] || 'pending',
    reviewer,
    decided_at: new Date().toISOString()
  }
}];
